using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int TotalCharged(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void S1_BronzeBasketOf10000CentsIsCharged9500Cents() =>
        Assert.Equal(9500, TotalCharged(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverBasketOf10000CentsIsCharged9000Cents() =>
        Assert.Equal(9000, TotalCharged(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldBasketOf10000CentsIsCharged8500Cents() =>
        Assert.Equal(8500, TotalCharged(LoyaltyTier.Gold, 10000));

    // Bronze customer with a tiny basket is charged a whole cent in their favour
    [Fact]
    public void S4_BronzeBasketOf7CentsIsCharged7Cents() =>
        Assert.Equal(7, TotalCharged(LoyaltyTier.Bronze, 7));
}

